<script setup lang="ts">
import {ref,computed} from 'vue'
import {onShow,onUnload} from '@dcloudio/uni-app'
import PageShell from '../../../components/PageShell.vue'
import AppIcon from '../../../components/AppIcon.vue'
import OcrProgress from '../../../components/OcrProgress.vue'
import {chooseImages,choosePDF,validateFiles,previewSelectedFile} from '../../../utils/upload'
import {uploadReport,UploadFailure} from '../../../api/report-upload'
import type {UploadReceipt} from '../../../api/report-upload'
import {requireRole,go} from '../../../utils/navigation'
import {fileSize,uid,toast,errorText} from '../../../utils/format'
import type {SelectedFile} from '../../../types'
const files=ref<SelectedFile[]>([]),consent=ref(false),busy=ref(false),error=ref(''),failedRaw=ref(''),failedStatus=ref(0)
const receipts=ref<Record<string,UploadReceipt>>({}),keys=ref<Record<string,string>>({}),expanded=ref<Record<string,boolean>>({})
const allUploaded=computed(()=>files.value.length>0&&files.value.every(f=>!!receipts.value[f.id]))
const progress=computed(()=>files.value.length?Math.round(files.value.reduce((s,f)=>s+f.progress,0)/files.value.length):0)
let task:UniApp.UploadTask|undefined,disposed=false
onShow(()=>requireRole('worker'))
onUnload(()=>{disposed=true;task?.abort()})
async function choose(kind:'camera'|'album'|'pdf'){if(busy.value)return;try{const added=kind==='pdf'?await choosePDF():await chooseImages(kind);validateFiles([...files.value,...added]);for(const f of added)keys.value[f.id]=uid();files.value.push(...added);error.value='';failedRaw.value=''}catch(e:any){if(!String(e?.errMsg||'').includes('cancel'))toast(errorText(e))}}
function remove(id:string){if(!busy.value&&!receipts.value[id]){files.value=files.value.filter(f=>f.id!==id);delete keys.value[id]}}
function newUpload(){files.value=[];receipts.value={};keys.value={};expanded.value={};consent.value=false;error.value='';failedRaw.value='';failedStatus.value=0}
async function submit(){
 if(busy.value||allUploaded.value)return
 try{validateFiles(files.value);if(!consent.value)throw new Error('请先阅读隐私说明并同意上传')}catch(e){toast(errorText(e));return}
 busy.value=true;error.value='';failedRaw.value='';failedStatus.value=0
 try{
  for(const file of files.value){
   if(disposed)break
   if(receipts.value[file.id])continue
   keys.value[file.id] ||= uid()
   const receipt=await uploadReport(file,keys.value[file.id],n=>file.progress=n,t=>task=t)
   receipts.value[file.id]=receipt;file.progress=100;task=undefined
  }
  if(!disposed&&files.value.length===1&&allUploaded.value){const receipt=receipts.value[files.value[0].id];go('/pages/worker/report-detail/index?id='+encodeURIComponent(receipt.reportId)+'&revision='+receipt.revision+'&uploaded=1')}
 }catch(e){if(!disposed){error.value=errorText(e);if(e instanceof UploadFailure){failedStatus.value=e.httpStatus;failedRaw.value=e.raw}}}finally{busy.value=false;task=undefined}
}
</script>
<template><PageShell title="上传体检报告" live><view class="content"><view class="upload-intro"><view class="upload-mark"><AppIcon name="cloud-upload" :size="38"/></view><text class="upload-title">上传一份报告，多一份健康守护</text><text class="help">图片或 PDF · 最多9个文件 · 每个20MB</text></view><view class="hint" style="margin-bottom:24rpx">每个文件会分别生成一份报告。同一报告的多页内容，请先合并为 PDF 后上传。</view><view class="upload-methods"><view @tap="choose('camera')"><AppIcon name="camera" :size="32"/><text>拍照上传</text></view><view @tap="choose('album')"><AppIcon name="image" :size="32"/><text>从相册选择</text></view><view class="pdf" @tap="choose('pdf')"><AppIcon name="file-text" :size="32"/><text>上传 PDF</text></view></view><view class="card"><view class="section-head"><text class="section-title">已选择文件 <text class="green-text">{{files.length?'('+files.length+')':''}}</text></text><text class="help">原始文件安全上传</text></view><view v-if="!files.length" class="empty-upload"><AppIcon name="files" color="gray" :size="32"/><text>请在上方选择报告文件</text></view><view v-for="f in files" :key="f.id" class="selected-file"><image v-if="f.type==='image'" :src="f.path" class="thumb" mode="aspectFill" @tap="previewSelectedFile(f).catch(e=>toast(errorText(e)))"/><view v-else class="pdf-thumb" @tap="previewSelectedFile(f).catch(e=>toast(errorText(e)))">PDF</view><view class="grow"><text class="file-name">{{f.name}}</text><text class="help">{{fileSize(f.size)}} {{receipts[f.id]?'· 已接收':busy?'· '+f.progress+'%':''}}</text></view><view v-if="!busy&&!receipts[f.id]" @tap="remove(f.id)"><AppIcon name="circle-x" color="gray" :size="21"/></view></view></view><view class="privacy" @tap="!busy&&(consent=!consent)"><view class="flex gap"><AppIcon name="shield-check" :size="20"/><text class="bold">隐私说明与上传授权</text><view class="consent-box" :class="{agreed:consent}"><AppIcon v-if="consent" name="check" color="white" :size="12"/></view></view><text class="privacy-text">报告仅用于职业健康管理，由后端处理并提供给获得授权的人员。不会默认向 AI 发送您的全部档案。勾选表示同意本次上传。</text><text class="green-text caption" @tap.stop="go('/pages/common/legal/index?type=privacy')">查看隐私政策 ›</text></view><view v-if="busy" class="card"><view class="between caption"><text>正在传输原件</text><text>{{progress}}%</text></view><progress :percent="progress" activeColor="#00995b" stroke-width="4" style="margin-top:20rpx"/></view><view v-if="error" class="alert">{{error}}。已成功的文件不会重复上传，可重试未完成文件。</view><view v-for="f in files.filter(f=>receipts[f.id])" :key="'receipt-'+f.id" class="card"><view class="section-head"><text class="section-title">后台已接收</text><text class="tag">HTTP {{receipts[f.id].httpStatus}}</text></view><text class="help">{{f.name}}</text><view class="info-line"><text>报告编号</text><text selectable class="receipt-id">{{receipts[f.id].reportId||'后台未返回'}}</text></view><view class="info-line"><text>报告版本</text><text selectable class="receipt-id">{{receipts[f.id].revision}}</text></view><OcrProgress :task="receipts[f.id].ocrTask" :job-id="receipts[f.id].jobId" compact/><button class="btn btn-soft small" style="margin:18rpx 0" @tap="go('/pages/worker/report-detail/index?id='+encodeURIComponent(receipts[f.id].reportId)+'&revision='+receipts[f.id].revision)">查看处理进度</button><view class="more" @tap="expanded[f.id]=!expanded[f.id]">{{expanded[f.id]?'收起回执':'查看后台回执'}} ⌄</view><text v-if="expanded[f.id]" selectable class="raw-response">{{receipts[f.id].raw}}</text></view><view v-if="failedRaw" class="card"><text class="help">{{failedStatus?'HTTP '+failedStatus:'请求未完成'}}</text><text selectable class="raw-response">{{failedRaw}}</text></view><button class="btn" :loading="busy" :disabled="busy||allUploaded" @tap="submit"><AppIcon name="cloud-upload" color="white" :size="22"/>{{allUploaded?'报告已全部接收':error?'重试未完成文件':busy?'正在提交报告':'安全提交报告'}}</button><text class="upload-footnote">文件传输完成与 OCR 识别是两个阶段，识别状态以后台返回为准</text><button v-if="allUploaded" class="btn btn-soft" style="margin-top:24rpx" @tap="newUpload">继续上传其他报告</button></view></PageShell></template>
<style scoped>.upload-intro{padding:10rpx 0 28rpx;text-align:center;display:flex;align-items:center;flex-direction:column;gap:14rpx}.upload-mark{background:#e3f3e9;border-radius:24rpx;display:flex;padding:23rpx;margin-bottom:5rpx}.upload-title{font-size:31rpx;font-weight:650}.upload-methods{display:flex;gap:18rpx;margin-bottom:28rpx}.upload-methods>view{flex:1;background:#eaf6ee;border-radius:22rpx;display:flex;align-items:center;flex-direction:column;gap:22rpx;padding:32rpx 5rpx;font-size:25rpx;font-weight:550}.upload-methods .pdf{background:#fff1eb}.empty-upload{display:flex;align-items:center;flex-direction:column;padding:35rpx 0 20rpx;gap:15rpx;font-size:24rpx;color:#9ba69f}.selected-file{display:flex;align-items:center;gap:20rpx;padding:22rpx 0;border-bottom:1px solid #f0f4f1}.thumb,.pdf-thumb{width:80rpx;height:90rpx;border-radius:12rpx}.pdf-thumb{background:#fff0e8;color:#e68054;display:flex;align-items:center;justify-content:center;font-size:22rpx;font-weight:650}.file-name{display:block;font-size:25rpx;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.form-line{display:flex;align-items:center;justify-content:space-between;gap:20rpx;padding:20rpx 0;font-size:25rpx}.form-line input{height:82rpx;background:#f7f9f8;border-radius:12rpx;padding:18rpx;width:420rpx;font-size:24rpx}.picker-value{display:flex;align-items:center;justify-content:space-between;gap:12rpx;background:#f7f9f8;border-radius:12rpx;padding:18rpx;min-width:420rpx}.privacy{background:#e9f5ed;border-radius:22rpx;padding:25rpx;margin-bottom:28rpx;font-size:26rpx}.privacy-text{display:block;font-size:23rpx;color:#6e8875;line-height:1.8;margin:12rpx 0 8rpx}.consent-box{width:32rpx;height:32rpx;border:1px solid #9cbea7;border-radius:7rpx;margin-left:auto;display:flex;align-items:center;justify-content:center}.agreed{background:#008f55;border-color:#008f55}.upload-footnote{display:block;text-align:center;font-size:22rpx;color:#9aa99f;margin-top:20rpx}.receipt-id{max-width:68%;word-break:break-all;font-size:23rpx}.raw-response{display:block;white-space:pre-wrap;word-break:break-all;font-size:22rpx;margin-top:20rpx}</style>
